// OTHVM — Prayer time reminders (Aladhan API — no LLM)
const TZ = 'Africa/Cairo';
const LAT = 30.584138;
const LON = 31.495866;
const METHOD = 5; // Egyptian General Authority of Survey
const SCHOOL = 0; // Standard (Shafi'i)
const WINDOW_MIN = 10; // الدقائق المسموح فيها بالإرسال بعد دخول الوقت

const PRAYERS = [
  ['Fajr', 'الفجر'],
  ['Dhuhr', 'الظهر'],
  ['Asr', 'العصر'],
  ['Maghrib', 'المغرب'],
  ['Isha', 'العشاء'],
];

const now = new Date();
const today = new Intl.DateTimeFormat('en-CA', { timeZone: TZ, year: 'numeric', month: '2-digit', day: '2-digit' }).format(now);
const nowHM = new Intl.DateTimeFormat('en-GB', { timeZone: TZ, hour: '2-digit', minute: '2-digit', hourCycle: 'h23' }).format(now);
const toMin = (hm) => {
  const p = String(hm).split(':');
  return Number(p[0]) * 60 + Number(p[1] || 0);
};
const nowM = toMin(nowHM);

const sd = $getWorkflowStaticData('global');
if (!sd.times || sd.times.date !== today) {
  const dmy = today.split('-').reverse().join('-');
  const res = await this.helpers.httpRequest({
    method: 'GET',
    url: 'https://api.aladhan.com/v1/timings/' + dmy + '?latitude=' + LAT + '&longitude=' + LON + '&method=' + METHOD + '&school=' + SCHOOL,
    json: true,
    timeout: 20000,
  });
  const t = res && res.data && res.data.timings ? res.data.timings : null;
  if (!t) return [];
  const clean = (v) => String(v || '').trim().split(' ')[0];
  sd.times = { date: today, list: {} };
  for (const p of PRAYERS) sd.times.list[p[0]] = clean(t[p[0]]);
}
if (!sd.sent || sd.sent.date !== today) sd.sent = { date: today, list: [] };

const fmt12 = (hm) => {
  const p = String(hm).split(':');
  const h = Number(p[0]);
  const m = Number(p[1] || 0);
  const period = h < 12 ? 'صباحاً' : 'مساءً';
  const h12 = ((h + 11) % 12) + 1;
  return h12 + ':' + String(m).padStart(2, '0') + ' ' + period;
};

const out = [];
const outPrayers = [];
for (const p of PRAYERS) {
  const en = p[0];
  const ar = p[1];
  const timeStr = sd.times.list[en];
  if (!timeStr) continue;
  const pM = toMin(timeStr);
  const due = nowM >= pM && nowM <= pM + WINDOW_MIN;
  if (!due) continue;
  if (sd.sent.list.indexOf(en) !== -1) continue;
  outPrayers.push(en);
  out.push('🕌 حان وقت صلاة ' + ar + ' — ' + fmt12(timeStr));
}

if (!out.length) return [];
return [{ json: { message: out.join('\n'), prayers: outPrayers } }];

// OTHVM — Calendar Check: تذكير بالمواعيد خلال نافذة زمنية (بدون LLM)
const evs = $input.all().map((i) => i.json).filter((j) => j && !j.error && j.start);

const WINDOW_H = 3; // نافذة التذكير (بالساعات) — تُبنى من CONFIG
const now = new Date();
const nowMs = now.getTime();
const inWin = nowMs + WINDOW_H * 3600 * 1000;
const candidates = [];
for (const ev of evs) {
  const s = ev.start || {};
  if (!s.dateTime) continue;
  const st = new Date(s.dateTime).getTime();
  if (st >= nowMs && st <= inWin && ev.id) candidates.push({ ev, st });
}
if (!candidates.length) return [];

const base = String($env.SUPABASE_URL || '').replace(/\/+$/, '');
const key = String($env.SUPABASE_SERVICE_KEY || '');
const since = new Date(nowMs - 24 * 3600 * 1000).toISOString();
let sentIds = [];
if (base && key) {
  try {
    const rows = await this.helpers.httpRequest({
      method: 'GET',
      url: base + '/rest/v1/sent_reminders_log?select=event_id&sent_at=gte.' + encodeURIComponent(since),
      headers: { apikey: key, Authorization: 'Bearer ' + key },
      json: true,
      timeout: 15000,
    });
    sentIds = (rows || []).map((r) => r.event_id);
  } catch (e) { sentIds = []; }
}
const due = candidates.filter((c) => sentIds.indexOf(c.ev.id) === -1).sort((a, b) => a.st - b.st);
if (!due.length) return [];

const pad = (n) => String(n).padStart(2, '0');
const fmt12 = (d) => {
  const hm = new Intl.DateTimeFormat('en-GB', { timeZone: 'Africa/Cairo', hour: '2-digit', minute: '2-digit', hourCycle: 'h23' }).format(d);
  const p = hm.split(':');
  const h = Number(p[0]);
  const period = h < 12 ? 'صباحاً' : 'مساءً';
  return (((h + 11) % 12) + 1) + ':' + pad(Number(p[1] || 0)) + ' ' + period;
};
const cairoDate = (d) => new Intl.DateTimeFormat('en-CA', { timeZone: 'Africa/Cairo', year: 'numeric', month: '2-digit', day: '2-digit' }).format(d);

const dayName = (d) => new Intl.DateTimeFormat('ar-EG-u-nu-latn', { timeZone: 'Africa/Cairo', weekday: 'long' }).format(d);
const todayStr = cairoDate(now);
const lines = ['⏰ تذكير بمواعيد قريبة:'];
for (const c of due) {
  const d = new Date(c.ev.start.dateTime);
  const when = cairoDate(d) === todayStr ? fmt12(d) : dayName(d) + ' ' + fmt12(d);
  const loc = c.ev.location ? ' 📍 ' + String(c.ev.location).slice(0, 40) : '';
  lines.push('• ' + when + ' — ' + (c.ev.summary || '(بدون عنوان)') + loc);
}
return [{ json: { message: lines.join('\n'), events: due.map((c) => ({ event_id: c.ev.id, event_title: String(c.ev.summary || '').slice(0, 150) })) } }];

// OTHVM — Weather Alert (Open-Meteo hourly — no LLM)
const TZ = 'Africa/Cairo';
const LAT = 30.584138;
const LON = 31.495866;
const TH = {
  heatC: 40,
  windKmh: 45,
  rainMm: 5,
  rainProb: 70,
  rainMmLight: 1,
  stormCode: 95,
};

const now = new Date();
const dPart = new Intl.DateTimeFormat('en-CA', { timeZone: TZ, year: 'numeric', month: '2-digit', day: '2-digit' }).format(now);
const hPart = new Intl.DateTimeFormat('en-GB', { timeZone: TZ, hour: '2-digit', hourCycle: 'h23' }).format(now);
const today = dPart;
const nowKey = dPart + 'T' + hPart + ':00';

const res = await this.helpers.httpRequest({
  method: 'GET',
  url: 'https://api.open-meteo.com/v1/forecast?latitude=' + LAT + '&longitude=' + LON + '&hourly=temperature_2m,precipitation,precipitation_probability,weathercode,windspeed_10m&timezone=Africa%2FCairo&forecast_days=2',
  json: true,
  timeout: 20000,
});
const H = res && res.hourly ? res.hourly : null;
if (!H || !Array.isArray(H.time)) return [];

const fmt12 = (hm) => {
  const p = String(hm).split(':');
  const h = Number(p[0]);
  const m = Number(p[1] || 0);
  const period = h < 12 ? 'صباحاً' : 'مساءً';
  const h12 = ((h + 11) % 12) + 1;
  return h12 + ':' + String(m).padStart(2, '0') + ' ' + period;
};
const windAr = (kmh) => {
  const n = Math.round(Number(kmh));
  if (!Number.isFinite(n)) return 'رياح متغيرة';
  if (n <= 15) return 'هواء هادئ';
  if (n <= 30) return 'نسيم خفيف';
  if (n <= 50) return 'رياح قوية';
  return 'رياح شديدة ⚠️';
};

const alerts = [];
let count = 0;
for (let i = 0; i < H.time.length; i++) {
  const t = H.time[i];
  if (t < nowKey) continue;
  count++;
  if (count > 24) break;
  const temp = Number(H.temperature_2m[i]);
  const code = Number(H.weathercode[i]);
  const mm = Number(H.precipitation[i] || 0);
  const prob = Number(H.precipitation_probability[i] || 0);
  const wind = Number(H.windspeed_10m[i]);
  const hm = t.slice(11, 16);
  if (code >= TH.stormCode) alerts.push({ type: 'storm', text: '⛈️ عاصفة رعدية متوقعة حوالي ' + fmt12(hm) });
  else if (mm >= TH.rainMm || (prob >= TH.rainProb && mm >= TH.rainMmLight)) alerts.push({ type: 'rain', text: '🌧️ أمطار غزيرة متوقعة حوالي ' + fmt12(hm) + (prob > 30 ? ' (احتمال ' + prob + '%)' : '') });
  if (temp >= TH.heatC) alerts.push({ type: 'heat', text: '🥵 حرارة شديدة متوقعة حوالي ' + fmt12(hm) + ' (' + Math.round(temp) + '°م)' });
  if (wind >= TH.windKmh) alerts.push({ type: 'wind', text: '💨 ' + windAr(wind) + ' متوقعة حوالي ' + fmt12(hm) });
}

const firstByType = {};
for (const a of alerts) if (!firstByType[a.type]) firstByType[a.type] = a;

const sd = $getWorkflowStaticData('global');
if (!sd.alerted || sd.alerted.date !== today) sd.alerted = { date: today, list: [] };

const toSend = Object.keys(firstByType).map((k) => firstByType[k]).filter((a) => sd.alerted.list.indexOf(a.type) === -1);
if (toSend.length === 0) return [];
const lines = ['⚠️ تنبيه طقس:'];
for (const a of toSend) lines.push('• ' + a.text);
return [{ json: { message: lines.join('\n'), types: toSend.map((a) => a.type) } }];

// OTHVM — Weather Tomorrow Check: طقس بكرة + مواعيد محتملة للخروج (بدون LLM)
let w = {};
try { w = $('Fetch Weather').first().json || {}; } catch (e) { w = {}; }
const f = w && w.ok && Array.isArray(w.forecast) && w.forecast[1] ? w.forecast[1] : null;
const WEATHER_AR = {
  'clear sky': 'سماء صافية',
  'mainly clear': 'صافية غالباً',
  'partly cloudy': 'غائم جزئياً',
  'overcast': 'غائم',
  'fog': 'ضباب',
  'depositing rime fog': 'ضباب متجمد',
  'light drizzle': 'رذاذ خفيف',
  'moderate drizzle': 'رذاذ متوسط',
  'dense drizzle': 'رذاذ كثيف',
  'light freezing drizzle': 'رذاذ متجمد خفيف',
  'dense freezing drizzle': 'رذاذ متجمد كثيف',
  'slight rain': 'مطر خفيف',
  'moderate rain': 'مطر متوسط',
  'heavy rain': 'مطر غزير',
  'light freezing rain': 'مطر متجمد خفيف',
  'heavy freezing rain': 'مطر متجمد غزير',
  'slight snow': 'ثلج خفيف',
  'moderate snow': 'ثلج متوسط',
  'heavy snow': 'ثلج غزير',
  'snow grains': 'حبيبات ثلج',
  'slight rain showers': 'زخات مطر خفيفة',
  'moderate rain showers': 'زخات مطر متوسطة',
  'violent rain showers': 'زخات مطر عنيفة',
  'slight snow showers': 'زخات ثلج خفيفة',
  'heavy snow showers': 'زخات ثلج غزيرة',
  'thunderstorm': 'عاصفة رعدية',
  'thunderstorm with slight hail': 'عاصفة رعدية مع برد خفيف',
  'thunderstorm with heavy hail': 'عاصفة رعدية مع برد غزير',
};
const weatherAr = (s) => WEATHER_AR[String(s || '').toLowerCase()] || 'طقس متغير';
const evs = $('Tomorrow Calendar').all().map((i) => i.json).filter((j) => j && !j.error && j.start);

const timed = evs.filter((ev) => ev.start && ev.start.dateTime);
const eligible = timed.filter((ev) => {
  if (ev.hangoutLink) return false;
  const loc = String(ev.location || '');
  if (/zoom|meet|online|remote|أونلاين|عن بعد/i.test(loc)) return false;
  const title = String(ev.summary || '').trim();
  if (/^sleep$/i.test(title) || /نوم/i.test(title)) return false;
  return true;
});

let bad = false;
let why = '';
let descAr = '';
if (f) {
  descAr = weatherAr(f.desc);
  const rain = Number(f.rain_chance || 0);
  const max = Number(f.max || 0);
  if (/عاصفة|غزير|عنيفة|متجمد|ثلج/.test(descAr)) { bad = true; why = descAr; }
  else if (rain >= 50) { bad = true; why = 'فرصة مطر ' + rain + '%'; }
  else if (max >= 40) { bad = true; why = 'حرارة ' + Math.round(max) + '°م'; }
}


const pad = (n) => String(n).padStart(2, '0');
const fmt12 = (d) => {
  const hm = new Intl.DateTimeFormat('en-GB', { timeZone: 'Africa/Cairo', hour: '2-digit', minute: '2-digit', hourCycle: 'h23' }).format(d);
  const p = hm.split(':');
  const h = Number(p[0]);
  const period = h < 12 ? 'صباحاً' : 'مساءً';
  return (((h + 11) % 12) + 1) + ':' + pad(Number(p[1] || 0)) + ' ' + period;
};
const cairoDate = (d) => new Intl.DateTimeFormat('en-CA', { timeZone: 'Africa/Cairo', year: 'numeric', month: '2-digit', day: '2-digit' }).format(d);


if (!bad || eligible.length === 0) return [];

const sd = $getWorkflowStaticData('global');
const todayStr = cairoDate(new Date());
if (sd.warnedOn === todayStr) return [];

const lines = ['⚠️ تحذير المساء — بكرة الطقس مش مناسب للخروج:'];
const tempRange = f ? Math.round(f.min) + '°م—' + Math.round(f.max) + '°م' : '';
const detail = (why !== descAr && descAr ? descAr + ' • ' : '') + tempRange;
lines.push('• الحالة: ' + why + (detail ? ' (' + detail + ')' : ''));
lines.push('');
lines.push('🗓 مواعيد بكرة المحتمل تأثرها (' + eligible.length + '):');
for (const ev of eligible.slice(0, 8)) lines.push('• ' + fmt12(new Date(ev.start.dateTime)) + ' — ' + (ev.summary || '(بدون عنوان)'));
lines.push('');
lines.push('خد احتياطك أو اجّل اللي تقدر عليه.');
return [{ json: { message: lines.join('\n'), warned_on: todayStr } }];

// Mark prayers sent only after Telegram accepted the aggregate message.
const src = $('Check Prayer Times').first().json || {};
const keys = Array.isArray(src.prayers) ? src.prayers : [];
if (!keys.length) return [];
const today = new Intl.DateTimeFormat('en-CA', { timeZone: 'Africa/Cairo', year: 'numeric', month: '2-digit', day: '2-digit' }).format(new Date());
const sd = $getWorkflowStaticData('global');
if (!sd.sent || sd.sent.date !== today) sd.sent = { date: today, list: [] };
for (const key of keys) if (sd.sent.list.indexOf(key) === -1) sd.sent.list.push(key);
return [{ json: { ok: true, prayers: keys } }];

// Log sent calendar reminders only after Telegram accepted the message.
const src = $('Filter Reminders').first().json || {};
const events = Array.isArray(src.events) ? src.events : [];
if (!events.length) return [];
const base = String($env.SUPABASE_URL || '').replace(/\/+$/, '');
const key = String($env.SUPABASE_SERVICE_KEY || '');
if (!base || !key) return [{ json: { ok: false, error: 'supabase env missing' } }];
let lastErr = '';
for (let attempt = 0; attempt < 3; attempt++) {
  try {
    await this.helpers.httpRequest({
      method: 'POST',
      url: base + '/rest/v1/sent_reminders_log',
      headers: { apikey: key, Authorization: 'Bearer ' + key, Prefer: 'return=representation' },
      body: events,
      json: true,
      timeout: 15000,
    });
    return [{ json: { ok: true, logged: events.length } }];
  } catch (e) { lastErr = String(e && e.message ? e.message : e); }
  await new Promise((r) => setTimeout(r, 500 * (attempt + 1)));
}
return [{ json: { ok: false, error: lastErr.slice(0, 300) } }];

// Mark weather alerts only after Telegram accepted the aggregate message.
const src = $('Check Weather Alert').first().json || {};
const types = Array.isArray(src.types) ? src.types : [];
if (!types.length) return [];
const today = new Intl.DateTimeFormat('en-CA', { timeZone: 'Africa/Cairo', year: 'numeric', month: '2-digit', day: '2-digit' }).format(new Date());
const sd = $getWorkflowStaticData('global');
if (!sd.alerted || sd.alerted.date !== today) sd.alerted = { date: today, list: [] };
for (const t of types) if (sd.alerted.list.indexOf(t) === -1) sd.alerted.list.push(t);
return [{ json: { ok: true, types } }];

// Mark the evening warning only after Telegram accepted the message.
const src = $('Check Tomorrow Plan').first().json || {};
const day = String(src.warned_on || '');
if (!day) return [];
const sd = $getWorkflowStaticData('global');
sd.warnedOn = day;
return [{ json: { ok: true, warned_on: day } }];
